<?php
/** Bộ xếp TKB độc lập: chỉ đọc PCCM, chỉ ghi kho nháp riêng cho tới khi công bố. */
require_once __DIR__.'/timetable_store.php';
if(!defined('CDS_TTB_FILE'))define('CDS_TTB_FILE',DATA_PATH.'/timetable_builder.json');

function ttb_default():array{return ['enabled'=>true,'settings'=>['days'=>[2,3,4,5,6,7],'morning_periods'=>5,'afternoon_periods'=>5,'attempts'=>40,'max_teacher_daily'=>7,'avoid_edges'=>true],'blocked'=>[],'groups'=>[],'plans'=>[],'active_plan'=>'','updated_at'=>''];}
function ttb_data():array{$base=ttb_default();$raw=load_json(CDS_TTB_FILE,[]);if(!is_array($raw))return$base;$data=array_merge($base,$raw);$data['settings']=array_merge($base['settings'],is_array($raw['settings']??null)?$raw['settings']:[]);foreach(['blocked','groups','plans']as$key)if(!is_array($data[$key]??null))$data[$key]=[];return$data;}
function ttb_save(array$data):bool{$data['updated_at']=date('c');return save_json(CDS_TTB_FILE,$data);}
function ttb_pccm_dir():string{return defined('PCCM_DATA_PATH')&&PCCM_DATA_PATH!==''?rtrim(PCCM_DATA_PATH,'/\\'):BASE_PATH.'/chuyenmon/data';}
function ttb_assignments():array{$dir=ttb_pccm_dir();$active=load_json($dir.'/active_version.json',[]);$vid=trim((string)($active['id']??''));if($vid===''){foreach((array)load_json($dir.'/versions.json',[])as$v)if(!empty($v['id'])){$vid=(string)$v['id'];break;}}$rows=$vid!==''?load_json($dir.'/assignments_'.$vid.'.json',[]):load_json($dir.'/assignments.json',[]);$manual=load_json($dir.'/manual_assignments.json',[]);foreach(is_array($manual)?$manual:[]as$r){$rv=trim((string)($r['version_id']??''));if($rv!==''&&$rv!==$vid)continue;$r['class']=$r['class']??$r['class_name']??'';$r['is_manual']=true;$rows[]=$r;}$out=[];foreach(is_array($rows)?$rows:[]as$r){$teacher=trim((string)($r['teacher']??''));$subject=trim((string)($r['subject']??''));$class=trim((string)($r['class']??$r['class_name']??''));$periods=(float)($r['periods']??0);if($teacher===''||$subject===''||$class===''||$periods<=0)continue;$id=trim((string)($r['id']??''))?:hash('sha256',$teacher.'|'.$subject.'|'.$class);$out[]=['id'=>$id,'teacher'=>$teacher,'subject'=>$subject,'class'=>$class,'periods'=>$periods,'note'=>(string)($r['note']??'')];}usort($out,fn($a,$b)=>strnatcasecmp($a['class'].'|'.$a['subject'],$b['class'].'|'.$b['subject']));return$out;}
function ttb_slot_key(int$day,string$session,int$period):string{return$day.'|'.$session.'|'.$period;}
function ttb_slots(array$settings):array{$out=[];foreach((array)($settings['days']??[2,3,4,5,6,7])as$day){foreach(['Sáng'=>(int)($settings['morning_periods']??5),'Chiều'=>(int)($settings['afternoon_periods']??5)]as$session=>$max)for($p=1;$p<=$max;$p++)$out[]=['day'=>(int)$day,'session'=>$session,'period'=>$p,'key'=>ttb_slot_key((int)$day,$session,$p)];}return$out;}
function ttb_group_map(array$groups):array{$map=[];foreach($groups as$g)foreach((array)($g['assignment_ids']??[])as$id)$map[(string)$id]=(string)($g['id']??'');return$map;}
function ttb_activities(array$assignments,array$groups):array{$byId=[];foreach($assignments as$a)$byId[$a['id']]=$a;$consumed=[];$out=[];
 foreach($groups as$g){$members=[];foreach((array)($g['assignment_ids']??[])as$id)if(isset($byId[$id]))$members[]=$byId[$id];if(count($members)<2)continue;$available=min(array_map(fn($m)=>max(0,(int)round($m['periods'])-(int)($consumed[$m['id']]??0)),$members));$count=min(max(1,(int)($g['periods']??1)),$available);if($count<1)continue;foreach($members as$m)$consumed[$m['id']]=(int)($consumed[$m['id']]??0)+$count;for($n=1;$n<=$count;$n++)$out[]=['id'=>(string)$g['id'].'_'.$n,'group_id'=>(string)$g['id'],'teacher'=>(string)($g['teacher']??$members[0]['teacher']),'subject'=>(string)($g['subject']??$members[0]['subject']),'classes'=>array_values(array_unique(array_column($members,'class'))),'fixed_day'=>(int)($g['day']??0),'fixed_session'=>(string)($g['session']??''),'fixed_period'=>(int)($g['period']??0),'credit_mode'=>(string)($g['credit_mode']??'per_class')];}
 foreach($assignments as$a){$remaining=max(0,(int)round($a['periods'])-(int)($consumed[$a['id']]??0));for($n=1;$n<=$remaining;$n++)$out[]=['id'=>$a['id'].'_'.$n,'assignment_id'=>$a['id'],'teacher'=>$a['teacher'],'subject'=>$a['subject'],'classes'=>[$a['class']],'fixed_day'=>0,'fixed_session'=>'','fixed_period'=>0,'credit_mode'=>'per_class'];}
 return$out;}
function ttb_blocked(array$data,string$teacher,string$key):bool{return!empty($data['blocked'][hash('sha256',$teacher.'|'.$key)]);}
function ttb_candidate_score(array$a,array$s,array$placed,array$settings):int{$score=random_int(0,9);$teacher=$a['teacher'];$day=$s['day'];$sameTeacherDay=[];$sameSubjectDay=0;foreach($placed as$p){if($p['teacher']===$teacher&&$p['day']===$day)$sameTeacherDay[]=$p;if($p['day']===$day&&$p['subject']===$a['subject']&&array_intersect($p['classes'],$a['classes']))$sameSubjectDay++;}$score+=$sameSubjectDay*45;$score+=max(0,count($sameTeacherDay)+1-(int)($settings['max_teacher_daily']??7))*120;if(!empty($settings['avoid_edges'])&&($s['period']===1||$s['period']===(($s['session']==='Sáng')?(int)$settings['morning_periods']:(int)$settings['afternoon_periods'])))$score+=8;if($sameTeacherDay){$periods=array_column(array_filter($sameTeacherDay,fn($p)=>$p['session']===$s['session']),'period');if($periods){$near=min(array_map(fn($p)=>abs($p-$s['period']),$periods));$score+=max(0,$near-1)*12;}}return$score;}
function ttb_validate_entries(array$entries,array$activities):array{$errors=[];$classBusy=[];$teacherBusy=[];$activityMap=[];foreach($activities as$a)$activityMap[$a['id']]=$a;foreach($entries as$e){$key=ttb_slot_key((int)$e['day'],(string)$e['session'],(int)$e['period']);$aid=(string)$e['activity_id'];foreach((array)$e['classes']as$c){$ck=$c.'|'.$key;if(isset($classBusy[$ck])&&$classBusy[$ck]!==$aid)$errors[]='Trùng lớp '.$c.' tại '.$key;$classBusy[$ck]=$aid;}$tk=$e['teacher'].'|'.$key;if(isset($teacherBusy[$tk])&&$teacherBusy[$tk]!==$aid)$errors[]='Trùng giáo viên '.$e['teacher'].' tại '.$key;$teacherBusy[$tk]=$aid;}return array_values(array_unique($errors));}
function ttb_generate(array$data,array$assignments,array$locked=[]):array{$settings=$data['settings'];$activities=ttb_activities($assignments,(array)$data['groups']);$slots=ttb_slots($settings);$best=null;$deadline=microtime(true)+8.0;$attempts=max(1,min(100,(int)($settings['attempts']??40)));
 for($attempt=0;$attempt<$attempts&&microtime(true)<$deadline;$attempt++){$placed=[];$classBusy=[];$teacherBusy=[];$lockedIds=[];foreach($locked as$e)if(!empty($e['locked'])){$placed[]=$e;$lockedIds[$e['activity_id']]=true;$key=ttb_slot_key($e['day'],$e['session'],$e['period']);foreach($e['classes']as$c)$classBusy[$c.'|'.$key]=true;$teacherBusy[$e['teacher'].'|'.$key]=true;}$todo=array_values(array_filter($activities,fn($a)=>empty($lockedIds[$a['id']])));shuffle($todo);usort($todo,function($a,$b){$fa=($a['fixed_day']?1000:0)+count($a['classes'])*100;$fb=($b['fixed_day']?1000:0)+count($b['classes'])*100;return$fb<=>$fa;});$unplaced=[];$score=0;
  foreach($todo as$a){$candidates=[];foreach($slots as$s){if($a['fixed_day']&&($s['day']!==$a['fixed_day']||($a['fixed_session']!==''&&$s['session']!==$a['fixed_session'])||($a['fixed_period']&&$s['period']!==$a['fixed_period'])))continue;if(ttb_blocked($data,$a['teacher'],$s['key']))continue;if(isset($teacherBusy[$a['teacher'].'|'.$s['key']]))continue;$bad=false;foreach($a['classes']as$c)if(isset($classBusy[$c.'|'.$s['key']])){$bad=true;break;}if($bad)continue;$candidates[]=['slot'=>$s,'score'=>ttb_candidate_score($a,$s,$placed,$settings)];}if(!$candidates){$unplaced[]=$a;continue;}usort($candidates,fn($x,$y)=>$x['score']<=>$y['score']);$pick=$candidates[0];$s=$pick['slot'];$entry=array_merge($a,['activity_id'=>$a['id'],'day'=>$s['day'],'session'=>$s['session'],'period'=>$s['period'],'locked'=>false]);$placed[]=$entry;$score+=$pick['score'];$teacherBusy[$a['teacher'].'|'.$s['key']]=true;foreach($a['classes']as$c)$classBusy[$c.'|'.$s['key']]=true;}
  $score+=count($unplaced)*100000;$candidate=['entries'=>$placed,'unplaced'=>$unplaced,'score'=>$score,'errors'=>ttb_validate_entries($placed,$activities)];if($best===null||$candidate['score']<$best['score'])$best=$candidate;if(!$unplaced&&$score<20)break;}
 $best=$best??['entries'=>[],'unplaced'=>$activities,'score'=>PHP_INT_MAX,'errors'=>[]];$best['id']='plan_'.date('YmdHis').'_'.bin2hex(random_bytes(2));$best['name']='Phương án '.date('d/m/Y H:i');$best['created_at']=date('c');return$best;}
function ttb_plan(array$data,string$id):?array{foreach((array)$data['plans']as$p)if(($p['id']??'')===$id)return$p;return null;}
function ttb_replace_plan(array&$data,array$plan):void{$found=false;foreach($data['plans']as&$p)if(($p['id']??'')===($plan['id']??'')){$p=$plan;$found=true;break;}unset($p);if(!$found)$data['plans'][]=$plan;$data['active_plan']=$plan['id'];$data['plans']=array_slice($data['plans'],-12);}
function ttb_publish(array$plan,string$name,string$from,string$to,array$user):array{if(!empty($plan['unplaced'])||!empty($plan['errors']))return['ok'=>false,'message'=>'Phương án còn tiết chưa xếp hoặc xung đột.'];$entries=[];foreach($plan['entries']as$e)foreach($e['classes']as$class)$entries[]=['day'=>(int)$e['day'],'session'=>(string)$e['session'],'period'=>(int)$e['period'],'class_raw'=>$class,'subject_raw'=>(string)$e['subject'],'teacher_raw'=>(string)$e['teacher'],'group_session_id'=>(string)($e['group_id']??''),'teacher_credit'=>($e['credit_mode']??'per_class')==='per_class'?1:1/max(1,count($e['classes']))];$versions=tt_versions();foreach($versions as&$v)$v['published']=false;unset($v);$version=['id'=>'tt_'.bin2hex(random_bytes(7)),'name'=>$name,'week_from'=>$from,'week_to'=>$to,'entries'=>$entries,'raw_values'=>['teacher'=>array_values(array_unique(array_column($entries,'teacher_raw'))),'class'=>array_values(array_unique(array_column($entries,'class_raw'))),'subject'=>array_values(array_unique(array_column($entries,'subject_raw')))],'published'=>true,'dashboard_visible'=>false,'source_name'=>'Xếp tự động CDS','builder_plan_id'=>$plan['id'],'created_by'=>$user['name']??'','created_at'=>date('c')];$versions[]=$version;if(!tt_save(CDS_TIMETABLE_VERSIONS,$versions))return['ok'=>false,'message'=>'Không lưu được phiên bản TKB.'];return['ok'=>true,'version'=>$version,'message'=>'Đã công bố phiên bản '.$name.'. TKB cũ vẫn được giữ trong Lịch sử.'];}
